  /**
   * Sudden Death: on the configured turn every living buddy drops to 1 HP and the water starts
   * climbing. It strikes once per match, and 1 rather than 0 keeps it out of the death phase:
   * nobody dies from the strike itself.
   * Returns true when it struck, so the turn can announce it after the usual turn banner.
   */
  private checkSuddenDeath(): boolean {
    const at = this.config.suddenDeath ?? 0;
    if (at <= 0 || this.turn !== at) return false;
    for (const b of this.buddies) {
      if (b.alive) b.hp = SUDDEN_DEATH_HP;
    }
    this.waterRising = true;
    else if (this.screen === 'setup') this.showTitle();
  }

  private returnFromHelp(): void {
    if (this.helpReturn === 'pause') this.showPause();
    else this.showTitle();
  }

  private onInput(e: Event): void {
    const input = e.target as HTMLInputElement;
    if (input.dataset.field === 'seed') {
      this.draft.seed = input.value.trim() || randomSeed();
      // Generating a map costs a few milliseconds, so wait for a pause in the typing.
      window.clearTimeout(this.previewTimer);
      this.previewTimer = window.setTimeout(() => {
        this.paintPreview();
      }, 250);
    }
    if (input.dataset.field === 'faction-name') {
      const i = Number(input.dataset.faction);
      this.draft.factions ??= ['', '', '', ''];
      this.draft.factions[i] = input.value.trim().slice(0, 24);
      for (const button of this.el.querySelectorAll<HTMLButtonElement>(`[data-action="faction"][data-value="${String(i)}"]`))
        button.textContent = this.factionName(i);
    }
    if (input.dataset.field === 'team-name') this.draft.teams[Number(input.dataset.team)].name = input.value || 'Team';
    if (input.dataset.field === 'buddy-name') {
      // An empty field would leave a nameless buddy in the HUD, so it falls back to what it was
      // called by default rather than to nothing.
      const team = defined(this.draft.teams[Number(input.dataset.team)], 'team');
      const at = Number(input.dataset.buddy);
      team.buddyNames[at] = input.value || `${team.name.slice(0, 6)} ${String(at + 1)}`;
    }
    this.persist();
  }

